  ('d0000000-0000-0000-0000-000000001201', 'In which year did Mahatma Gandhi return to India from South Africa?', 'c0000010-0003-0000-0000-000000000089', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001202', 'Where was Mahatma Gandhi''s first Satyagraha movement launched in India in 1917 to support oppressed indigo sharecroppers?', 'c0000010-0003-0000-0000-000000000089', 'Easy', 'MCQ'),
